1	package com.example.starter.service;
2	
3	import java.time.Clock;
4	import java.time.Duration;
5	import java.time.LocalDateTime;
6	import java.util.List;
7	import java.util.function.Supplier;
8	
9	import com.fasterxml.jackson.core.JsonProcessingException;
10	import com.fasterxml.jackson.databind.ObjectMapper;
11	
12	import org.springframework.dao.DuplicateKeyException;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.support.TransactionTemplate;
15	
16	import com.example.starter.domain.PlanStatus;
17	import com.example.starter.store.IdempotencyRepository;
18	import com.example.starter.store.PlanRepository;
19	import com.example.starter.store.PlanRepository.PlanRow;
20	import com.example.starter.web.ApiException;
21	import com.example.starter.web.dto.PlanResponse;
22	import com.example.starter.web.dto.Requests.ApplyRequest;
23	import com.example.starter.web.dto.Requests.CancelRequest;
24	import com.example.starter.web.dto.Requests.ConfirmRequest;
25	import com.example.starter.web.dto.Requests.RescheduleRequest;
26	import com.example.starter.web.dto.Requests.ScheduleRequest;
27	import com.example.starter.web.dto.Requests.SettleRequest;
28	import com.example.starter.web.dto.Requests.StartRequest;
29	
30	/**
31	 * 引航计划核心服务：状态流转（申请→编排→确认→执行→核销）、工时校验、
32	 * 资源锁定（确认/改期与锁定同事务）与 requestId 幂等控制。
33	 *
34	 * <p>幂等语义：指纹覆盖 requestId 与全部业务字段；同键同参返回首次结果，
35	 * 同键异参返回 409。幂等记录先于业务写入（同事务），并发下同键请求由主键串行化，
36	 * 后到者重放首次结果。</p>
37	 */
38	@Service
39	public class PilotPlanService {
40	
41	    /** 迟到取消临界：执行前 2 小时（恰满 2 小时仍可免费取消）。 */
42	    static final long CANCEL_NOTICE_MINUTES = 2 * 60;
43	
44	    private final PlanRepository plans;
45	    private final IdempotencyRepository idem;
46	    private final TransactionTemplate tx;
47	    private final ObjectMapper objectMapper;
48	    private final Clock clock;
49	
50	    public PilotPlanService(PlanRepository plans, IdempotencyRepository idem,
51	                            TransactionTemplate tx, ObjectMapper objectMapper, Clock clock) {
52	        this.plans = plans;
53	        this.idem = idem;
54	        this.tx = tx;
55	        this.objectMapper = objectMapper;
56	        this.clock = clock;
57	    }
58	
59	    /** 申请引航计划。 */
60	    public PlanResponse apply(ApplyRequest request) {
61	        String fingerprint = IdempotencyRepository.fingerprint("apply", request.requestId(),
62	                request.applicant(), request.shipName(), request.planStart(), request.planEnd());
63	        return idempotent("apply", request.requestId(), fingerprint, () -> {
64	            validateTimeRange(request.planStart(), request.planEnd());
65	            long planId = plans.insertPlan(request.requestId(), request.applicant(),
66	                    request.shipName(), request.planStart(), request.planEnd(), now());
67	            return toResponse(plans.findById(planId).orElseThrow(), List.of(), false);
68	        });
69	    }
70	
71	    /** 编排：绑定引航员、拖轮组合与潮水窗口，校验窗口包含关系与工时规则。 */
72	    public PlanResponse schedule(ScheduleRequest request) {
73	        String fingerprint = IdempotencyRepository.fingerprint("schedule", request.requestId(),
74	                request.planId(), request.pilotId(), request.tugIds(),
75	                request.tideStart(), request.tideEnd());
76	        return idempotent("schedule", request.requestId(), fingerprint, () -> {
77	            PlanRow plan = lockPlan(request.planId());
78	            requireStatus(plan, PlanStatus.APPLIED, "仅申请状态的计划可编排");
79	            validateWindow(plan, request.tideStart(), request.tideEnd());
80	            if (!plans.pilotExists(request.pilotId())) {
81	                throw ApiException.badRequest("引航员不存在: " + request.pilotId());
82	            }
83	            for (Long tugId : request.tugIds()) {
84	                if (!plans.tugExists(tugId)) {
85	                    throw ApiException.badRequest("拖轮不存在: " + tugId);
86	                }
87	            }
88	            validatePilotAssignable(request.pilotId(), plan.planStart(), plan.planEnd(), plan.id());
89	            plans.updateSchedule(plan.id(), request.pilotId(), request.tideStart(), request.tideEnd(),
90	                    plan.planStart(), plan.planEnd(), now());
91	            plans.replacePlanTugs(plan.id(), request.tugIds());
92	            return toResponse(plans.findById(plan.id()).orElseThrow(), request.tugIds(), false);
93	        });
94	    }
95	
96	    /** 确认：校验资源占用后，引航员与拖轮在同一事务内同时锁定。 */
97	    public PlanResponse confirm(ConfirmRequest request) {
98	        String fingerprint = IdempotencyRepository.fingerprint("confirm", request.requestId(),
99	                request.planId());
100	        return idempotent("confirm", request.requestId(), fingerprint, () -> {
101	            PlanRow plan = lockPlan(request.planId());
102	            requireStatus(plan, PlanStatus.SCHEDULED, "仅已编排的计划可确认");
103	            List<Long> tugIds = plans.findTugIds(plan.id());
104	            if (tugIds.isEmpty()) {
105	                throw ApiException.conflict("计划未绑定拖轮组合，不可确认");
106	            }
107	            lockResources(plan.pilotId(), tugIds);
108	            checkResourceFree(plan, tugIds);
109	            plans.insertLock(plan.id(), "PILOT", plan.pilotId(), plan.planStart(), plan.planEnd());
110	            for (Long tugId : tugIds) {
111	                plans.insertLock(plan.id(), "TUG", tugId, plan.planStart(), plan.planEnd());
112	            }
113	            plans.updateStatus(plan.id(), PlanStatus.CONFIRMED, now());
114	            return toResponse(plans.findById(plan.id()).orElseThrow(), tugIds, false);
115	        });
116	    }
117	
118	    /** 开始执行：同一引航员同时刻只允许一条执行中计划。 */
119	    public PlanResponse start(StartRequest request) {
120	        String fingerprint = IdempotencyRepository.fingerprint("start", request.requestId(),
121	                request.planId());
122	        return idempotent("start", request.requestId(), fingerprint, () -> {
123	            PlanRow plan = lockPlan(request.planId());
124	            requireStatus(plan, PlanStatus.CONFIRMED, "仅已确认的计划可开始执行");
125	            if (plans.existsExecutingOverlap(plan.pilotId(), plan.planStart(), plan.planEnd(), plan.id())) {
126	                throw ApiException.conflict("同一引航员同时刻已存在执行中计划");
127	            }
128	            plans.updateStatus(plan.id(), PlanStatus.EXECUTING, now());
129	            return toResponse(plans.findById(plan.id()).orElseThrow(), plans.findTugIds(plan.id()), false);
130	        });
131	    }
132	
133	    /** 核销：执行结束后释放资源锁。 */
134	    public PlanResponse settle(SettleRequest request) {
135	        String fingerprint = IdempotencyRepository.fingerprint("settle", request.requestId(),
136	                request.planId());
137	        return idempotent("settle", request.requestId(), fingerprint, () -> {
138	            PlanRow plan = lockPlan(request.planId());
139	            requireStatus(plan, PlanStatus.EXECUTING, "仅执行中的计划可核销");
140	            plans.deleteLocksByPlanId(plan.id());
141	            plans.updateStatus(plan.id(), PlanStatus.SETTLED, now());
142	            return toResponse(plans.findById(plan.id()).orElseThrow(), plans.findTugIds(plan.id()), false);
143	        });
144	    }
145	
146	    /**
147	     * 取消：执行前 2 小时外免费取消；恰满 2 小时仍可取消；不足 2 小时
148	     * 合成违约记录后取消；已到达执行时刻不可取消。
149	     */
150	    public PlanResponse cancel(CancelRequest request) {
151	        String fingerprint = IdempotencyRepository.fingerprint("cancel", request.requestId(),
152	                request.planId());
153	        return idempotent("cancel", request.requestId(), fingerprint, () -> {
154	            PlanRow plan = lockPlan(request.planId());
155	            if (plan.status() != PlanStatus.APPLIED && plan.status() != PlanStatus.SCHEDULED
156	                    && plan.status() != PlanStatus.CONFIRMED) {
157	                throw ApiException.conflict("当前状态不可取消: " + plan.status());
158	            }
159	            if (!now().isBefore(plan.planStart())) {
160	                throw ApiException.conflict("已到达计划执行时刻，不可取消");
161	            }
162	            long leadMinutes = Duration.between(now(), plan.planStart()).toMinutes();
163	            boolean violation = leadMinutes < CANCEL_NOTICE_MINUTES;
164	            if (violation) {
165	                plans.insertViolation(plan.id(), "迟到取消：距执行不足 2 小时", leadMinutes, now());
166	            }
167	            plans.deleteLocksByPlanId(plan.id());
168	            plans.updateStatus(plan.id(), PlanStatus.CANCELLED, now());
169	            return toResponse(plans.findById(plan.id()).orElseThrow(),
170	                    plans.findTugIds(plan.id()), violation);
171	        });
172	    }
173	
174	    /** 改期：重新校验工时与拖轮占用，结论与重新锁定在同一事务内完成。 */
175	    public PlanResponse reschedule(RescheduleRequest request) {
176	        String fingerprint = IdempotencyRepository.fingerprint("reschedule", request.requestId(),
177	                request.planId(), request.planStart(), request.planEnd(),
178	                request.tideStart(), request.tideEnd());
179	        return idempotent("reschedule", request.requestId(), fingerprint, () -> {
180	            PlanRow plan = lockPlan(request.planId());
181	            if (plan.status() != PlanStatus.SCHEDULED && plan.status() != PlanStatus.CONFIRMED) {
182	                throw ApiException.conflict("当前状态不可改期: " + plan.status());
183	            }
184	            validateTimeRange(request.planStart(), request.planEnd());
185	            if (request.planStart().isBefore(request.tideStart())
186	                    || request.planEnd().isAfter(request.tideEnd())) {
187	                throw ApiException.badRequest("计划时间须落在潮水窗口内");
188	            }
189	            validatePilotAssignable(plan.pilotId(), request.planStart(), request.planEnd(), plan.id());
190	            List<Long> tugIds = plans.findTugIds(plan.id());
191	            lockResources(plan.pilotId(), tugIds);
192	            for (Long tugId : tugIds) {
193	                if (!plans.findOverlappingLocks("TUG", tugId,
194	                        request.planStart(), request.planEnd(), plan.id()).isEmpty()) {
195	                    throw ApiException.conflict("拖轮 " + tugId + " 在改期时段已被占用");
196	                }
197	            }
198	            if (!plans.findOverlappingLocks("PILOT", plan.pilotId(),
199	                    request.planStart(), request.planEnd(), plan.id()).isEmpty()) {
200	                throw ApiException.conflict("引航员在改期时段已被锁定");
201	            }
202	            // 结论与重新锁定同事务：先释放旧锁，再按新时段一次性锁定
203	            plans.deleteLocksByPlanId(plan.id());
204	            if (plan.status() == PlanStatus.CONFIRMED) {
205	                plans.insertLock(plan.id(), "PILOT", plan.pilotId(),
206	                        request.planStart(), request.planEnd());
207	                for (Long tugId : tugIds) {
208	                    plans.insertLock(plan.id(), "TUG", tugId, request.planStart(), request.planEnd());
209	                }
210	            }
211	            plans.updateReschedule(plan.id(), request.tideStart(), request.tideEnd(),
212	                    request.planStart(), request.planEnd(), now());
213	            return toResponse(plans.findById(plan.id()).orElseThrow(), tugIds, false);
214	        });
215	    }
216	
217	    // ---------- 内部通用逻辑 ----------
218	
219	    private LocalDateTime now() {
220	        return LocalDateTime.now(clock);
221	    }
222	
223	    /**
224	     * 幂等执行框架：同事务内先落幂等记录再执行业务，并发同键由主键串行化；
225	     * 后到者捕获唯一键冲突后重放首次结果，同键异参返回 409。
226	     */
227	    private PlanResponse idempotent(String operation, String requestId, String fingerprint,
228	                                    Supplier<PlanResponse> action) {
229	        try {
230	            return tx.execute(status -> {
231	                var existing = idem.find(requestId);
232	                if (existing.isPresent()) {
233	                    return replay(existing.get(), fingerprint);
234	                }
235	                idem.insert(requestId, operation, fingerprint, "", now());
236	                PlanResponse response = action.get();
237	                idem.updateResponse(requestId, toJson(response));
238	                return response;
239	            });
240	        } catch (DuplicateKeyException e) {
241	            var existing = idem.find(requestId);
242	            if (existing.isPresent()) {
243	                return replay(existing.get(), fingerprint);
244	            }
245	            throw ApiException.conflict("幂等冲突，请重试");
246	        }
247	    }
248	
249	    /** 重放首次结果；指纹不一致（同键异参）返回 409。 */
250	    private PlanResponse replay(IdempotencyRepository.IdemRow existing, String fingerprint) {
251	        if (!existing.fingerprint().equals(fingerprint)) {
252	            throw ApiException.conflict("requestId 已存在且业务参数不一致");
253	        }
254	        try {
255	            return objectMapper.readValue(existing.responseBody(), PlanResponse.class);
256	        } catch (JsonProcessingException e) {
257	            throw new IllegalStateException("幂等响应反序列化失败", e);
258	        }
259	    }
260	
261	    private String toJson(PlanResponse response) {
262	        try {
263	            return objectMapper.writeValueAsString(response);
264	        } catch (JsonProcessingException e) {
265	            throw new IllegalStateException("幂等响应序列化失败", e);
266	        }
267	    }
268	
269	    private PlanRow lockPlan(long planId) {
270	        return plans.findByIdForUpdate(planId)
271	                .orElseThrow(() -> ApiException.notFound("计划不存在: " + planId));
272	    }
273	
274	    private void requireStatus(PlanRow plan, PlanStatus expected, String message) {
275	        if (plan.status() != expected) {
276	            throw ApiException.conflict(message + "，当前状态: " + plan.status());
277	        }
278	    }
279	
280	    private void validateTimeRange(LocalDateTime start, LocalDateTime end) {
281	        if (!start.isBefore(end)) {
282	            throw ApiException.badRequest("计划开始时间须早于结束时间");
283	        }
284	    }
285	
286	    /** 潮水窗口自身合法且覆盖计划时间（半开区间 [tideStart, tideEnd)）。 */
287	    private void validateWindow(PlanRow plan, LocalDateTime tideStart, LocalDateTime tideEnd) {
288	        if (!tideStart.isBefore(tideEnd)) {
289	            throw ApiException.badRequest("潮水窗口起点须早于终点");
290	        }
291	        if (plan.planStart().isBefore(tideStart) || plan.planEnd().isAfter(tideEnd)) {
292	            throw ApiException.badRequest("计划时间须落在潮水窗口内");
293	        }
294	    }
295	
296	    /**
297	     * 校验引航员可排：时段不与既有计划重叠，且满足连续作业 4 小时强制休息 1 小时、
298	     * 单日累计不超过 10 小时的工时规则。
299	     */
300	    private void validatePilotAssignable(long pilotId, LocalDateTime start, LocalDateTime end,
301	                                         long excludePlanId) {
302	        List<PlanRow> active = plans.findActivePlansForPilot(pilotId,
303	                start.minusDays(2), end.plusDays(2), excludePlanId);
304	        for (PlanRow other : active) {
305	            if (other.planStart().isBefore(end) && other.planEnd().isAfter(start)) {
306	                throw ApiException.conflict("引航员在该时段已有计划: " + other.id());
307	            }
308	        }
309	        List<WorkHourValidator.Interval> intervals = active.stream()
310	                .map(p -> new WorkHourValidator.Interval(p.planStart(), p.planEnd()))
311	                .toList();
312	        WorkHourValidator.validate(intervals, new WorkHourValidator.Interval(start, end))
313	                .ifPresent(message -> {
314	                    throw ApiException.conflict(message);
315	                });
316	    }
317	
318	    /**
319	     * 按固定顺序（先引航员后拖轮升序）对资源行加行锁，
320	     * 串行化并发确认/改期，避免检查与插入之间的占用竞态。
321	     */
322	    private void lockResources(long pilotId, List<Long> tugIds) {
323	        plans.lockPilotRow(pilotId);
324	        tugIds.stream().sorted().forEach(plans::lockTugRow);
325	    }
326	
327	    /** 确认前校验引航员与拖轮组合在计划时段均无其他锁占用（半开区间）。 */
328	    private void checkResourceFree(PlanRow plan, List<Long> tugIds) {        if (!plans.findOverlappingLocks("PILOT", plan.pilotId(),
329	                plan.planStart(), plan.planEnd(), plan.id()).isEmpty()) {
330	            throw ApiException.conflict("引航员在该时段已被锁定");
331	        }
332	        for (Long tugId : tugIds) {
333	            if (!plans.findOverlappingLocks("TUG", tugId,
334	                    plan.planStart(), plan.planEnd(), plan.id()).isEmpty()) {
335	                throw ApiException.conflict("拖轮 " + tugId + " 在该时段已被锁定");
336	            }
337	        }
338	    }
339	
340	    private PlanResponse toResponse(PlanRow plan, List<Long> tugIds, boolean violationCreated) {
341	        return new PlanResponse(plan.id(), plan.status().name(), plan.pilotId(), tugIds,
342	                plan.planStart(), plan.planEnd(), plan.tideStart(), plan.tideEnd(), violationCreated);
343	    }
344	}
