1	package com.example.starter.service;
2	
3	import java.time.Duration;
4	import java.time.LocalDate;
5	import java.time.LocalDateTime;
6	import java.util.ArrayList;
7	import java.util.Comparator;
8	import java.util.List;
9	import java.util.Optional;
10	
11	/**
12	 * 引航员工时校验（纯函数，便于单元测试）：
13	 * <ul>
14	 *   <li>连续作业满 4 小时（恰满 4 小时即判定）后，须强制休息 1 小时才允许开始下一条计划；
15	 *       相邻计划间隔不足 1 小时视为连续作业。</li>
16	 *   <li>单日累计引航不超过 10 小时，恰 10 小时合法；计划按开始时刻归属自然日。</li>
17	 * </ul>
18	 */
19	public final class WorkHourValidator {
20	
21	    /** 连续作业上限：分钟。恰满即触发强制休息。 */
22	    public static final long CONTINUOUS_LIMIT_MINUTES = 4 * 60;
23	    /** 强制休息时长：分钟。间隔不足该值视为连续作业。 */
24	    public static final long REQUIRED_REST_MINUTES = 60;
25	    /** 单日累计上限：分钟。恰满合法。 */
26	    public static final long DAILY_LIMIT_MINUTES = 10 * 60;
27	
28	    /** 计划占用区间（半开区间 [start, end)）。 */
29	    public record Interval(LocalDateTime start, LocalDateTime end) {
30	        public long durationMinutes() {
31	            return Duration.between(start, end).toMinutes();
32	        }
33	    }
34	
35	    private WorkHourValidator() {
36	    }
37	
38	    /**
39	     * 校验在既有计划基础上新增 [newStart, newEnd) 是否违反工时规则。
40	     *
41	     * @param existing 引航员既有有效计划区间（不含被改期/替换的计划本身）
42	     * @param newPlan  新增或改期后的计划区间
43	     * @return 违规则返回错误信息，否则为空
44	     */
45	    public static Optional<String> validate(List<Interval> existing, Interval newPlan) {
46	        List<Interval> all = new ArrayList<>(existing);
47	        all.add(newPlan);
48	        all.sort(Comparator.comparing(Interval::start));
49	
50	        Optional<String> dailyViolation = checkDaily(all, newPlan);
51	        if (dailyViolation.isPresent()) {
52	            return dailyViolation;
53	        }
54	        return checkContinuousRest(all, all.indexOf(newPlan));
55	    }
56	
57	    /** 单日累计：新计划所在自然日的累计工时须 ≤ 10 小时（恰 10 小时合法）。 */
58	    private static Optional<String> checkDaily(List<Interval> all, Interval newPlan) {
59	        LocalDate day = newPlan.start().toLocalDate();
60	        long total = all.stream()
61	                .filter(i -> i.start().toLocalDate().equals(day))
62	                .mapToLong(Interval::durationMinutes)
63	                .sum();
64	        if (total > DAILY_LIMIT_MINUTES) {
65	            return Optional.of("引航员单日累计引航 " + total + " 分钟，超过 10 小时上限");
66	        }
67	        return Optional.empty();
68	    }
69	
70	    /**
71	     * 连续作业与强制休息：自新计划起向后检查，每条计划开始前的连续作业块
72	     * （间隔不足 1 小时即串联）达到 4 小时（恰满即判定）则违规。
73	     */
74	    private static Optional<String> checkContinuousRest(List<Interval> sorted, int fromIndex) {
75	        for (int i = Math.max(fromIndex, 0); i < sorted.size(); i++) {
76	            long continuousBefore = continuousWorkBefore(sorted, i);
77	            if (continuousBefore >= CONTINUOUS_LIMIT_MINUTES) {
78	                return Optional.of("引航员连续作业已达 " + continuousBefore
79	                        + " 分钟（满 4 小时），须强制休息 1 小时");
80	            }
81	        }
82	        return Optional.empty();
83	    }
84	
85	    /**
86	     * 计算第 index 条计划开始之前的连续作业块总工时：
87	     * 向前串联所有间隔不足 1 小时的相邻计划，累计其作业时长。
88	     */
89	    private static long continuousWorkBefore(List<Interval> sorted, int index) {
90	        long total = 0;
91	        LocalDateTime nextStart = sorted.get(index).start();
92	        for (int i = index - 1; i >= 0; i--) {
93	            Interval prev = sorted.get(i);
94	            long gap = Duration.between(prev.end(), nextStart).toMinutes();
95	            if (gap >= REQUIRED_REST_MINUTES || gap < 0) {
96	                // 已休息满 1 小时（或区间异常重叠），连续作业中断
97	                break;
98	            }
99	            total += prev.durationMinutes();
100	            nextStart = prev.start();
101	        }
102	        return total;
103	    }
104	}
