    SWITCHED,
    /** 已撤回：切换前撤回，接班预占已释放，原引航员保留。 */
    WITHDRAWN,
    /** 核销关闭：核销与切换竞争中由核销关闭，接班预占已释放。 */
    CLOSED
}

