            @NotNull Long pilotId,
            @NotEmpty List<Long> tugIds,
            @NotNull LocalDateTime tideStart,
            @NotNull LocalDateTime tideEnd) {
    }

    /** 确认：同一事务内锁定引航员与拖轮。 */
    public record ConfirmRequest(
            @NotBlank String requestId,
            @NotNull Long planId) {
    }

